    /**
     * A notification for one user, for several, or for a channel's audience. Users outside the channel's audience
     * are not delivered to: their recipient has status <code>no_access</code>.
     *
     * @param externalUserId Exactly one of <code>external_user_id</code>, <code>external_user_ids</code> and
     * <code>to_audience</code> is required.
     * @param externalUserIds Sends to several users at once (at most 1000).
     * @param toAudience Sends to every paired user in the channel's audience, resolved when you send.
     * @param data Template data, sent as given: its keys are never renamed.
     * @param idempotencyKey Opts this send in to retries of 429 and 503. Sent as the Idempotency-Key header, never
     * in the body. The hub ignores it today, so a retried send is at-least-once.
     */
    public record Message(
            String externalUserId,
            List<String> externalUserIds,
            Boolean toAudience,
            String channel,
            Level level,
            String title,
            String subtitle,
            String body,
            String imageUrl,
            String templateId,
            Object data,
            String sound,
            List<Action> actions,
            String collapseId,
            PageOptions page,
            String idempotencyKey) {

        public Message {
            externalUserIds = externalUserIds == null ? null : List.copyOf(externalUserIds);
            actions = actions == null ? null : List.copyOf(actions);
        }

        /** Starts a {@code Message} with the fields it needs; the setters of the {@link Builder} add the rest. */
        public static Builder builder(String channel, String title, String body) {
            return new Builder()
                    .channel(Objects.requireNonNull(channel, "channel"))
                    .title(Objects.requireNonNull(title, "title"))
                    .body(Objects.requireNonNull(body, "body"));
        }

        /** A builder that starts from this {@code Message}. */
        public Builder toBuilder() {
            return new Builder()
                    .externalUserId(externalUserId)
                    .externalUserIds(externalUserIds)
                    .toAudience(toAudience)
                    .channel(channel)
                    .level(level)
                    .title(title)
                    .subtitle(subtitle)
                    .body(body)
                    .imageUrl(imageUrl)
                    .templateId(templateId)
                    .data(data)
                    .sound(sound)
                    .actions(actions)
                    .collapseId(collapseId)
                    .page(page)
                    .idempotencyKey(idempotencyKey);
        }

        /** A message for one user. */
        public static Builder builder(String externalUserId, String channel, String title, String body) {
            return builder(channel, title, body).externalUserId(Objects.requireNonNull(externalUserId, "externalUserId"));
        }

        /** A message for several users at once (at most 1000). */
        public static Builder forUsers(List<String> externalUserIds, String channel, String title, String body) {
            return builder(channel, title, body).externalUserIds(Objects.requireNonNull(externalUserIds, "externalUserIds"));
        }

        /** A message for every paired user in the channel's audience, resolved when you send. */
        public static Builder forAudience(String channel, String title, String body) {
            return builder(channel, title, body).toAudience(true);
        }

        /** Builds a {@link Message}. */
        public static final class Builder {
            private String externalUserId;
            private List<String> externalUserIds;
            private Boolean toAudience;
            private String channel;
            private Level level;
            private String title;
            private String subtitle;
            private String body;
            private String imageUrl;
            private String templateId;
            private Object data;
            private String sound;
            private List<Action> actions;
            private String collapseId;
            private PageOptions page;
            private String idempotencyKey;

            private Builder() {}

            /**
             * Exactly one of <code>external_user_id</code>, <code>external_user_ids</code> and
             * <code>to_audience</code> is required.
             */
            public Builder externalUserId(String externalUserId) {
                this.externalUserId = externalUserId;
                return this;
            }

            /** Sends to several users at once (at most 1000). */
            public Builder externalUserIds(List<String> externalUserIds) {
                this.externalUserIds = externalUserIds;
                return this;
            }

            /** Sends to every paired user in the channel's audience, resolved when you send. */
            public Builder toAudience(Boolean toAudience) {
                this.toAudience = toAudience;
                return this;
            }

            public Builder channel(String channel) {
                this.channel = channel;
                return this;
            }

            public Builder level(Level level) {
                this.level = level;
                return this;
            }

            public Builder title(String title) {
                this.title = title;
                return this;
            }

            public Builder subtitle(String subtitle) {
                this.subtitle = subtitle;
                return this;
            }

            public Builder body(String body) {
                this.body = body;
                return this;
            }

            public Builder imageUrl(String imageUrl) {
                this.imageUrl = imageUrl;
                return this;
            }

            public Builder templateId(String templateId) {
                this.templateId = templateId;
                return this;
            }

            /** Template data, sent as given: its keys are never renamed. */
            public Builder data(Object data) {
                this.data = data;
                return this;
            }

            public Builder sound(String sound) {
                this.sound = sound;
                return this;
            }

            public Builder actions(List<Action> actions) {
                this.actions = actions;
                return this;
            }

            public Builder collapseId(String collapseId) {
                this.collapseId = collapseId;
                return this;
            }

            public Builder page(PageOptions page) {
                this.page = page;
                return this;
            }

            /**
             * Opts this send in to retries of 429 and 503. Sent as the Idempotency-Key header, never in the body.
             * The hub ignores it today, so a retried send is at-least-once.
             */
            public Builder idempotencyKey(String idempotencyKey) {
                this.idempotencyKey = idempotencyKey;
                return this;
            }

            public Message build() {
                return new Message(
                        externalUserId,
                        externalUserIds,
                        toAudience,
                        channel,
                        level,
                        title,
                        subtitle,
                        body,
                        imageUrl,
                        templateId,
                        data,
                        sound,
                        actions,
                        collapseId,
                        page,
                        idempotencyKey);
            }
        }

        ObjectNode toWire() {
            ObjectNode o = Json.MAPPER.createObjectNode();
            Json.put(o, "external_user_id", externalUserId);
            if (externalUserIds != null && !externalUserIds.isEmpty()) {
                ArrayNode arr = o.putArray("external_user_ids");
                for (String item : externalUserIds) {
                    arr.add(item);
                }
            }
            if (toAudience != null) {
                o.put("to_audience", toAudience);
            }
            Json.put(o, "channel", channel);
            if (level != null) {
                o.put("level", level.wire());
            }
            Json.put(o, "title", title);
            Json.put(o, "subtitle", subtitle);
            Json.put(o, "body", body);
            Json.put(o, "image_url", imageUrl);
            Json.put(o, "template_id", templateId);
            if (data != null) {
                o.set("data", Json.tree(data));
            }
            Json.put(o, "sound", sound);
            if (actions != null && !actions.isEmpty()) {
                ArrayNode arr = o.putArray("actions");
                for (Action item : actions) {
                    arr.add(item.toWire());
                }
            }
            Json.put(o, "collapse_id", collapseId);
            if (page != null) {
                o.set("page", page.toWire());
            }
            return o;
        }
    }

