    /**
     * The answer to a send. For a send to one <code>external_user_id</code> the other fields describe that
     * recipient; for several users or an audience they are empty and each message is under <code>recipients</code>.
     *
     * @param recipients One entry per user.
     */
    public record MessageResult(
            String messageId,
            Level level,
            Integer devices,
            String status,
            List<Delivery> deliveries,
            List<Recipient> recipients) {

        public MessageResult {
            deliveries = deliveries == null ? null : List.copyOf(deliveries);
            recipients = recipients == null ? null : List.copyOf(recipients);
        }

        static MessageResult fromWire(JsonNode w) {
            return new MessageResult(
                    Json.optStr(w.get("message_id")),
                    Level.fromWire(Json.optStr(w.get("level"))),
                    Json.optInt(w.get("devices")),
                    Json.optStr(w.get("status")),
                    Json.list(w.get("deliveries"), Delivery::fromWire),
                    Json.list(w.get("recipients"), Recipient::fromWire));
        }
    }

    /**
     * A message's status and per-device deliveries.
     *
     * @param status One of queued, delivered, undeliverable, paging, acked, expired.
     * @param ackedAt When a page was acknowledged; absent until then.
     * @param ackedBy Who acknowledged a page: their external user id.
     * @param ackedByName The display name of whoever acknowledged, only when they have one.
     */
    public record MessageStatus(
            String messageId,
            String status,
            Level level,
            int attempts,
            List<Delivery> deliveries,
            Instant ackedAt,
            String ackedBy,
            String ackedByName) {

        public MessageStatus {
            deliveries = deliveries == null ? null : List.copyOf(deliveries);
        }

        static MessageStatus fromWire(JsonNode w) {
            return new MessageStatus(
                    Json.str(w.get("message_id")),
                    Json.str(w.get("status")),
                    Level.fromWire(Json.optStr(w.get("level"))),
                    (int) Json.num(w.get("attempts")),
                    Json.list(w.get("deliveries"), Delivery::fromWire),
                    Json.instant(w.get("acked_at")),
                    Json.optStr(w.get("acked_by")),
                    Json.optStr(w.get("acked_by_name")));
        }
    }

