    /**
     * Tunes a page (level <code>page</code>). A zero or absent field means the hub default.
     *
     * @param intervalSeconds Seconds between resends (hub default 120).
     * @param maxRetries Resends before the page expires (hub default 5).
     */
    public record PageOptions(
            Integer intervalSeconds,
            Integer maxRetries,
            PageAck ack) {

        /** Starts a {@code PageOptions} with the fields it needs; the setters of the {@link Builder} add the rest. */
        public static Builder builder() {
            return new Builder();
        }

        /** A builder that starts from this {@code PageOptions}. */
        public Builder toBuilder() {
            return new Builder()
                    .intervalSeconds(intervalSeconds)
                    .maxRetries(maxRetries)
                    .ack(ack);
        }

        /** Page options with an interval and a retry count; who must acknowledge stays at the hub default. */
        public static PageOptions of(int intervalSeconds, int maxRetries) {
            return builder().intervalSeconds(intervalSeconds).maxRetries(maxRetries).build();
        }

        /** Page options that only set who must acknowledge; interval and retries stay at the hub defaults. */
        public static PageOptions ack(PageAck ack) {
            return builder().ack(ack).build();
        }

        /** A copy that asks for the given acknowledgement mode. */
        public PageOptions withAck(PageAck ack) {
            return toBuilder().ack(ack).build();
        }

        /** Builds a {@link PageOptions}. */
        public static final class Builder {
            private Integer intervalSeconds;
            private Integer maxRetries;
            private PageAck ack;

            private Builder() {}

            /** Seconds between resends (hub default 120). */
            public Builder intervalSeconds(Integer intervalSeconds) {
                this.intervalSeconds = intervalSeconds;
                return this;
            }

            /** Resends before the page expires (hub default 5). */
            public Builder maxRetries(Integer maxRetries) {
                this.maxRetries = maxRetries;
                return this;
            }

            public Builder ack(PageAck ack) {
                this.ack = ack;
                return this;
            }

            public PageOptions build() {
                return new PageOptions(
                        intervalSeconds,
                        maxRetries,
                        ack);
            }
        }

        ObjectNode toWire() {
            ObjectNode o = Json.MAPPER.createObjectNode();
            if (intervalSeconds != null) {
                o.put("interval_s", intervalSeconds);
            }
            if (maxRetries != null) {
                o.put("max_retries", maxRetries);
            }
            if (ack != null) {
                o.put("ack", ack.wire());
            }
            return o;
        }
    }

