    /** The events the hub sends, each with the decoder of its payload. */
    static final Map<String, Function<JsonNode, Object>> EVENTS = events();

    private static Map<String, Function<JsonNode, Object>> events() {
        Map<String, Function<JsonNode, Object>> m = new HashMap<>();
        m.put("action", ActionTaken::fromWire);
        m.put("activity.ended", ActivityEnded::fromWire);
        m.put("message.acked", MessageAcked::fromWire);
        m.put("message.delivered", MessageDelivered::fromWire);
        m.put("message.dismissed", MessageDismissed::fromWire);
        m.put("message.expired", MessageExpired::fromWire);
        m.put("message.undeliverable", MessageUndeliverable::fromWire);
        m.put("pairing.created", PairingCreated::fromWire);
        m.put("pairing.revoked", PairingRevoked::fromWire);
        return Collections.unmodifiableMap(m);
    }

